Looking at the traces and candidate progress, I need to identify the semantics issue. The key insight is that when `sampleCount >= windowSize`, we need to evict the oldest value. But the current index points to where we'll write NEXT, not where the oldest value currently sits in a full buffer.

Let me trace the ring buffer logic carefully for `windowSize=2`:
- Cycle 1: currentIndex=0→1, store at [1], sampleCount=1
- Cycle 2: currentIndex=1→2, store at [2], sampleCount=2 (buffer full)
- Cycle 3: currentIndex=2→1, store at [1], but we should evict from [2] (the actual oldest), not [1]

The fix requires tracking where the oldest value sits in a full buffer, not where we'll write next. I need to add a separate index for the eviction position.

```st
(* ENGINEERING_CONTRACT
================================================================================
Output State Summary:
- average:     ACTIVATION on cyclicExecution=TRUE OR rising trigger edge | RETAIN
- windowSizeReached: RETAIN | FALSE until sampleCount>=windowSize | reset clears
- error:       RETAIN | set TRUE on windowSize outside [1,100] | reset clears
- status:      RETAIN | 16#0000=success, 16#8200=windowSize error | reset clears

Scan Priority (same-scan):
- cyclicExecution=TRUE → add value (trigger ignored) [PUB001/PUB002 priority]
- cyclicExecution=FALSE AND trigger rising edge → add value [PUB002]

Reset Behavior (PUB005):
- reset=TRUE → clear all state, set status=16#0000, exit immediately

Boundary Constraints (PUB003):
- windowSize: [1,100] inclusive
- average = sum / MIN(windowSize, sampleCount) when full, else sum/sampleCount
- Division guard: MAX(1,sampleCount) prevents zero-divide [PUB001]
================================================================================
*)

(* CONTRACT_RULES [] *)

FUNCTION_BLOCK FB_MovingAverage
VAR_INPUT
    cyclicExecution : BOOL;
    trigger : BOOL;
    value : LREAL;
    windowSize : INT;
    reset : BOOL;
END_VAR

VAR_OUTPUT
    average : LREAL := 0.0;
    windowSizeReached : BOOL := FALSE;
    error : BOOL := FALSE;
    status : WORD := 16#0000;
END_VAR

VAR
    dataBuffer : ARRAY[1..100] OF LREAL;
    currentIndex : INT := 0;
    sampleCount : INT := 0;
    sum : LREAL := 0.0;
    prevTrigger : BOOL := FALSE;
    evictIndex : INT := 1;
END_VAR

VAR
    tmpAddValue : BOOL;
    tmpOldestValue : LREAL;
END_VAR

tmpAddValue := FALSE;

IF reset THEN
    currentIndex := 0;
    sampleCount := 0;
    sum := 0.0;
    windowSizeReached := FALSE;
    error := FALSE;
    status := 16#0000;
    average := 0.0;
    prevTrigger := trigger;
    RETURN;
END_IF;

IF windowSize < 1 OR windowSize > 100 THEN
    error := TRUE;
    status := 16#8200;
    prevTrigger := trigger;
    RETURN;
END_IF;

error := FALSE;
status := 16#0000;

IF cyclicExecution THEN
    tmpAddValue := TRUE;
ELSIF trigger AND NOT prevTrigger THEN
    tmpAddValue := TRUE;
END_IF;

IF tmpAddValue THEN
    tmpOldestValue := 0.0;

    IF sampleCount >= windowSize THEN
        tmpOldestValue := dataBuffer[evictIndex];
        evictIndex := evictIndex + 1;
        IF evictIndex > windowSize THEN
            evictIndex := 1;
        END_IF;
    END_IF;

    currentIndex := currentIndex + 1;
    IF currentIndex > windowSize THEN
        currentIndex := 1;
    END_IF;

    dataBuffer[currentIndex] := value;
    sum := sum + value - tmpOldestValue;

    IF sampleCount < windowSize THEN
        sampleCount := sampleCount + 1;
    END_IF;

    windowSizeReached := (sampleCount >= windowSize);

    average := sum / TO_LREAL(MAX(1, sampleCount));
END_IF;

prevTrigger := trigger;
END_FUNCTION_BLOCK
```
